# Generated by Phase: IMPLEMENT | Feature: EVOL-053
"""Test-case traceability (EVOL-053): one machine-readable home for the case → test link, ratcheted.

config      `config/quality.json → traceability`: `home` {kind, pattern} — the ONE place a test states the case it
            proves (`pytest-marker`: `@pytest.mark.case("FEAT-001/TC-01")`; `title-tag`: `test("[FEAT-001/TC-01] …")`),
            the regex carrying a named group `id`; `id_pattern` — the case grammar (the id part; the feature part is
            the plan folder, `docs/spec/{FEATURE}/test_plan.md`, so a link is always `FEATURE/CASE`); `plans` — the
            glob of the plans; `test_roots` — root-anchored globs of the test files; `baseline` — the shrink-only
            debt file. `required: false` + `reason` for a repo with no plans (this framework: its tests are the T2
            suites). The key absent = RED, never a fault.
declared    every case a plan declares: the first cell of a table row, qualified by the plan's feature. A first cell
            that looks like a case id but fails the grammar is red.
links       every link under the test roots by the home's pattern, with its file:line (conftest files are never
            scanned: fixtures and the plugin, not tests). A link naming no declared case is red (as wrong as a case
            with no test); a malformed id is red.
check       case → test, never test → case: every declared case has a linking test, or sits in the baseline. The
            baseline may only shrink: an entry now linked is red until removed; an entry naming no declared case is red.
baseline    `--init` records the unlinked set once (refused when the file exists); `--refresh` removes entries that
            are linked or gone — never adds.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from .common import GateFault, key, tracked_files
from .seal import _norm_path, _root_match

HOMES = {
    "pytest-marker": r'@pytest\.mark\.case\(\s*["\'](?P<id>[^"\']*)["\']\s*\)',
    "title-tag": r'(?:\btest|\bit|\bdescribe|\bt\.Run)\s*\(\s*["\'`]\[(?P<id>[^\]]*)\]',
}
DEFAULT_ID = r"^(?:AC|TC-API|TC|REL-[A-Z]+|UX|A11Y|BRAND|LAYOUT)-\d{2,}$"
FEATURE = re.compile(r"^[A-Z][A-Z0-9]*-[0-9A-Z]+(?:-[0-9A-Z]+)*$")
LOOKS_LIKE_ID = re.compile(r"^[A-Z][A-Z0-9-]*-\d+[A-Za-z0-9-]*$")
TEXT_SUFFIXES = {".py", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".go", ".rs", ".java", ".kt", ".rb", ".php", ".cs", ".feature"}


def cfg(repo: Path) -> dict:
    t = key(repo, "traceability", default=None)
    if not isinstance(t, dict):
        raise GateFault("config key `traceability` is missing from config/quality.json — the home of the case → test link, its grammar, the plans, the test roots and the baseline live there (SETUP materialises it; SETUP --upgrade adds it)")
    required = t.get("required", True)
    if not isinstance(required, bool):
        raise GateFault("traceability.required must be true or false")
    out = {"required": required, "reason": str(t.get("reason") or "")}
    if not required:
        return out
    home = t.get("home") if isinstance(t.get("home"), dict) else {}
    kind = str(home.get("kind") or "")
    pattern = home.get("pattern") or HOMES.get(kind)
    if not pattern:
        raise GateFault(f"traceability.home.kind `{kind or '(none)'}` is not one of {', '.join(HOMES)} and no `pattern` is given — the home is the one place a test states its case")
    try:
        rx = re.compile(str(pattern), re.M)
    except re.error as e:
        raise GateFault(f"traceability.home.pattern is not a regex: {e}") from None
    if "id" not in rx.groupindex:
        raise GateFault("traceability.home.pattern must carry a named group `id`")
    try:
        idrx = re.compile(str(t.get("id_pattern") or DEFAULT_ID))
    except re.error as e:
        raise GateFault(f"traceability.id_pattern is not a regex: {e}") from None
    roots = t.get("test_roots", ["tests/**", "e2e/**"])
    if not isinstance(roots, list) or not roots or not all(isinstance(x, str) for x in roots):
        raise GateFault("traceability.test_roots must be a non-empty list of globs")
    out.update({"kind": kind, "home": rx, "id": idrx, "plans": str(t.get("plans") or "docs/spec/*/test_plan.md"),
                "roots": roots, "baseline": _norm_path(str(t.get("baseline") or "docs/project_log/traceability_baseline.json"))})
    return out


def _plans(repo: Path, c: dict) -> list[str]:
    return sorted(p for p in tracked_files(repo) if _root_match(_norm_path(p), [c["plans"]]))


def declared(repo: Path, c: dict) -> tuple[dict[str, str], list[dict]]:
    """qualified id → `plan:line`; malformed first cells as findings."""
    out: dict[str, str] = {}
    bad: list[dict] = []
    for plan in _plans(repo, c):
        feature = Path(plan).parent.name
        if not FEATURE.match(feature):
            bad.append({"path": plan, "reason": f"plan folder `{feature}` is not a feature id — plans live at docs/spec/{{FEATURE}}/"}); continue
        for n, line in enumerate((repo / plan).read_text(encoding="utf-8", errors="replace").splitlines(), 1):
            m = re.match(r"^\|\s*([^|]*?)\s*\|", line)
            if not m:
                continue
            cell = m.group(1).strip().strip("`*")
            if not cell or cell.upper() == "ID" or set(cell) <= set("-: "):
                continue
            if c["id"].match(cell):
                out.setdefault(f"{feature}/{cell}", f"{plan}:{n}")
            elif LOOKS_LIKE_ID.match(cell):
                bad.append({"path": f"{plan}:{n}", "reason": f"`{cell}` looks like a case id but fails the grammar traceability.id_pattern"})
    return out, bad


def links(repo: Path, c: dict) -> tuple[dict[str, list[str]], list[dict]]:
    """qualified id → [file:line]; malformed links as findings."""
    out: dict[str, list[str]] = {}
    bad: list[dict] = []
    for rel in tracked_files(repo):
        p = _norm_path(rel)
        if not _root_match(p, c["roots"]) or Path(p).suffix not in TEXT_SUFFIXES or Path(p).name.startswith("conftest"):
            continue   # a conftest holds fixtures and the plugin itself, never a test that proves a case
        text = (repo / rel).read_text(encoding="utf-8", errors="replace")
        for m in c["home"].finditer(text):
            line = text.count("\n", 0, m.start()) + 1
            raw = m.group("id").strip()
            feat, _, case = raw.partition("/")
            if not (feat and case) or not FEATURE.match(feat) or not c["id"].match(case):
                bad.append({"path": f"{p}:{line}", "reason": f"`{raw}` is not a case link — the form is FEATURE/CASE (e.g. FEAT-001/TC-01) with CASE matching traceability.id_pattern"})
                continue
            out.setdefault(f"{feat}/{case}", []).append(f"{p}:{line}")
    return out, bad


def read_baseline(repo: Path, c: dict) -> list[str]:
    p = repo / c["baseline"]
    if not p.is_file():
        return []
    try:
        d = json.loads(p.read_text(encoding="utf-8"))
    except (OSError, ValueError) as e:
        raise GateFault(f"the baseline {c['baseline']} is unreadable ({e}) — fix or delete it and --baseline --init again") from None
    items = d.get("unlinked") if isinstance(d, dict) else d
    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise GateFault(f"the baseline {c['baseline']} must carry `unlinked`: a list of qualified case ids")
    return sorted(set(items))


def check(repo: Path) -> dict:
    try:
        c = cfg(repo)
    except GateFault as e:
        return {"ok": False, "required": True, "reason": str(e), "findings": [], "cases": []}
    if not c["required"]:
        if not c["reason"]:
            return {"ok": False, "required": True, "reason": "traceability.required is false without a `reason` — say why this repo declares no test plan (fail closed)", "findings": [], "cases": []}
        return {"ok": True, "required": False, "reason": c["reason"], "findings": [], "cases": []}
    dec, bad_dec = declared(repo, c)
    lnk, bad_lnk = links(repo, c)
    base = read_baseline(repo, c)
    findings = list(bad_dec) + list(bad_lnk)
    for qid in sorted(set(lnk) - set(dec)):
        findings.append({"path": lnk[qid][0], "reason": f"`{qid}` names no case any plan declares — an unknown link is as wrong as a case with no test"})
    unlinked = sorted(q for q in dec if q not in lnk)
    new_debt = [q for q in unlinked if q not in base]
    for q in new_debt:
        findings.append({"path": dec[q], "reason": f"`{q}` has no linking test (the home: {c['kind']}) and is not in the baseline — link it or it is red"})
    shrink = sorted(q for q in base if q in lnk)
    for q in shrink:
        findings.append({"path": c["baseline"], "reason": f"`{q}` is linked now — the baseline only shrinks: remove it (gate.py traceability --baseline --refresh)"})
    stale = sorted(q for q in base if q not in dec)
    for q in stale:
        findings.append({"path": c["baseline"], "reason": f"`{q}` names no declared case any more — stale debt, remove it (gate.py traceability --baseline --refresh)"})
    cases = [{"id": q, "plan": dec[q], "tests": lnk.get(q, []), "status": "linked" if q in lnk else ("unlinked-baseline" if q in base else "unlinked")} for q in sorted(dec)]
    n_dec, n_lnk = len(dec), sum(1 for q in dec if q in lnk)
    reason = f"{n_dec} case(s) declared, {n_lnk} linked, {len(unlinked)} unlinked ({len([q for q in unlinked if q in base])} in the baseline)"
    return {"ok": not findings, "required": True, "home": c["kind"], "declared": n_dec, "linked": n_lnk, "unlinked": unlinked, "baseline": base,
            "new_debt": new_debt, "shrink": shrink, "stale": stale, "unknown": sorted(set(lnk) - set(dec)), "findings": findings, "cases": cases, "reason": reason}


def baseline(repo: Path, init: bool = False, refresh: bool = False) -> dict:
    c = cfg(repo)
    if not c["required"]:
        raise GateFault(f"traceability is not required in this repo ({c['reason']}) — no baseline to write")
    p = repo / c["baseline"]
    dec, _ = declared(repo, c)
    lnk, _ = links(repo, c)
    unlinked = sorted(q for q in dec if q not in lnk)
    if init:
        if p.is_file():
            raise GateFault(f"the baseline {c['baseline']} exists — it only shrinks (--refresh); delete it by decision if it must be re-taken")
        items = unlinked
        removed = []
    elif refresh:
        old = read_baseline(repo, c)
        items = [q for q in old if q in unlinked]
        removed = [q for q in old if q not in items]
    else:
        raise GateFault("--baseline needs --init (record the debt once) or --refresh (shrink it)")
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps({"_doc": "Test-case traceability baseline (EVOL-053): the cases unlinked at adoption. New cases must link; this list only shrinks (python3 scripts/gate.py traceability --baseline --refresh).", "unlinked": items}, indent=2) + "\n", encoding="utf-8")
    return {"ok": True, "path": c["baseline"], "unlinked": items, "removed": removed}


def render(res: dict) -> str:
    if not res.get("required", True):
        return f"traceability: n/a — {res['reason']}"
    if res["ok"]:
        return f"traceability: ok — {res['reason']} (home: {res.get('home')})"
    lines = [f"traceability: RED — {res['reason']}" if res.get("cases") is not None and res.get("declared") is not None else f"traceability: RED — {res['reason']}"]
    for f in res["findings"][:20]:
        lines.append(f"  {f['path']}: {f['reason']}")
    if len(res["findings"]) > 20:
        lines.append(f"  … {len(res['findings']) - 20} more")
    return "\n".join(lines)
